  render: (p, ctx) => {
    const fittedName = ctx.autoFit(p.name, {
      maxWidth: 900,
      maxLines: 2,
      maxFontSize: 62,
      minFontSize: 30,
      lineHeight: 1.15,
    });
    const fontFamily = Array.from(new Set(ctx.fonts.map((f) => f.name))).join(
      ", ",
    );
    const langColor = getLanguageColor(p.language);

    return (
      <div
        style={{
          display: "flex",
          width: "100%",
          height: "100%",
          backgroundColor: "#0d1117",
          color: "#f0f6fc",
          fontFamily,
          padding: 48,
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            flex: 1,
            width: "100%",
            height: "100%",
            backgroundColor: "#161b22",
            border: "1px solid #30363d",
            borderRadius: 20,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              display: "flex",
              width: "100%",
              height: 4,
              backgroundColor: "#38bdf8",
            }}
          />

          <div
            style={{
              display: "flex",
              flexDirection: "column",
              justifyContent: "space-between",
              flex: 1,
              padding: "48px 56px",
            }}
          >
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: 24,
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: 20,
                  overflow: "hidden",
                }}
              >
                <svg
                  width={44}
