                REPOSITORY
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  },
});

export interface AutoFitOptions {
  /** Available horizontal space for text in pixels. */
  maxWidth: number;
  /** Target maximum number of lines before reducing font size. Defaults to 2. */
  maxLines?: number;
  /** Starting/maximum font size in pixels. Defaults to 68. */
  maxFontSize?: number;
  /** Minimum font size in pixels. Defaults to 36. */
  minFontSize?: number;
  /** Line height multiplier passed back to the caller. Defaults to 1.18. */
  lineHeight?: number;
}

export interface AutoFitResult {
  fontSize: number;
  lineHeight: number;
  estimatedLines: number;
  overflowsAtMinSize: boolean;
}

const NARROW_ASCII = new Set([
  " ",
  "!",
  "'",
  ",",
  "-",
  ".",
  ":",
  ";",
  "I",
  "|",
  "i",
  "j",
  "l",
  "t",
]);

const WIDE_CHARS = new Set([
  "@",
  "%",
  "M",
  "W",
  "m",
  "w",
  "Ж",
  "Ф",
  "Ш",
  "Щ",
  "Ы",
  "Ю",
  "ж",
  "ф",
  "ш",
  "щ",
  "ы",
  "ю",
]);

function isFullwidthOrJapanese(cp: number): boolean {
  return (
    (cp >= 0x3000 && cp <= 0x30ff) ||
    (cp >= 0x31f0 && cp <= 0x31ff) ||
    (cp >= 0x3400 && cp <= 0x4dbf) ||
    (cp >= 0x4e00 && cp <= 0x9fff) ||
    (cp >= 0xf900 && cp <= 0xfaff) ||
    (cp >= 0xff00 && cp <= 0xffef)
  );
}

function charWidthInEm(ch: string): number {
  if (NARROW_ASCII.has(ch)) return 0.34;
  if (WIDE_CHARS.has(ch)) return 0.88;

  const cp = ch.codePointAt(0);
  if (cp === undefined) return 0.58;

  if (isFullwidthOrJapanese(cp)) return 1.0;

  // Uppercase Latin and Cyrillic letters
  if (
    (cp >= 0x0041 && cp <= 0x005a) ||
    (cp >= 0x0410 && cp <= 0x042f) ||
    cp === 0x0401
  ) {
    return 0.72;
  }

  return 0.58;
}

export function estimateTextMetrics(text: string): {
  totalEm: number;
  longestTokenEm: number;
  hasJapanese: boolean;
} {
  let totalEm = 0;
  let currentTokenEm = 0;
  let longestTokenEm = 0;
  let hasJapanese = false;

  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp !== undefined && isFullwidthOrJapanese(cp)) {
      hasJapanese = true;
    }

    const w = charWidthInEm(ch);
    totalEm += w;

    if (
      ch === " " ||
      ch === "\t" ||
      ch === "\n" ||
      ch === "/" ||
      ch === "-"
    ) {
      if (currentTokenEm > longestTokenEm) {
        longestTokenEm = currentTokenEm;
      }
      currentTokenEm = 0;
    } else if (cp !== undefined && isFullwidthOrJapanese(cp)) {
      // Satori can wrap CJK characters at character boundaries.
      if (currentTokenEm > longestTokenEm) {
        longestTokenEm = currentTokenEm;
      }
      if (w > longestTokenEm) {
        longestTokenEm = w;
      }
      currentTokenEm = 0;
    } else {
      currentTokenEm += w;
    }
  }

  if (currentTokenEm > longestTokenEm) {
    longestTokenEm = currentTokenEm;
  }

  return { totalEm, longestTokenEm, hasJapanese };
}

/**
 * Simple v1 script-aware heuristic that steps font size down from `maxFontSize`
 * to `minFontSize` until estimated wrapped lines fit within `maxLines` and the
 * longest unbroken word fits within `maxWidth`.
 */
export function autoFit(
  text: string,
  options: AutoFitOptions,
): AutoFitResult {
  const maxWidth = Math.max(1, options.maxWidth);
  const maxLines = Math.max(1, options.maxLines ?? 2);
  const maxFontSize = Math.max(8, options.maxFontSize ?? 68);
  const minFontSize = Math.max(8, Math.min(maxFontSize, options.minFontSize ?? 36));
  const lineHeight = options.lineHeight ?? 1.18;

  const trimmed = text.trim();
  if (!trimmed) {
    return {
      fontSize: maxFontSize,
      lineHeight,
      estimatedLines: 1,
      overflowsAtMinSize: false,
    };
  }

  const { totalEm, longestTokenEm, hasJapanese } = estimateTextMetrics(trimmed);
  const packingFactor = hasJapanese ? 0.95 : 0.88;
  const effectiveWidth = maxWidth * packingFactor;
  const step = 2;

  for (let size = maxFontSize; size >= minFontSize; size -= step) {
    const estimatedLines = Math.max(
      1,
      Math.ceil((totalEm * size) / effectiveWidth),
    );
    const longestFits = longestTokenEm * size <= maxWidth;
    if (estimatedLines <= maxLines && longestFits) {
      return {
        fontSize: size,
        lineHeight,
        estimatedLines,
        overflowsAtMinSize: false,
      };
    }
  }

  const minEstimatedLines = Math.max(
    1,
    Math.ceil((totalEm * minFontSize) / effectiveWidth),
  );
  const minFits =
    minEstimatedLines <= maxLines && longestTokenEm * minFontSize <= maxWidth;

  return {
    fontSize: minFontSize,
    lineHeight,
    estimatedLines: minEstimatedLines,
    overflowsAtMinSize: !minFits,
  };
}

import type { ReactElement } from "react";
import { z } from "zod";
import type { AutoFitOptions, AutoFitResult } from "./auto-fit";
import { findUnsupportedScripts, type LoadedFont, type ScriptId } from "./fonts";

export interface TemplateRenderContext {
  width: number;
  height: number;
  fonts: LoadedFont[];
  detectedScripts: ScriptId[];
  autoFit: (text: string, options: AutoFitOptions) => AutoFitResult;
}

export interface TemplateDefinition<TSchema extends z.ZodObject = z.ZodObject> {
  /** Unique kebab-case identifier matching the folder name under registry/templates/<id>. */
  id: string;
  /** Human-readable template name. */
  name: string;
  /** Short description of the card design. */
  description: string;
  /** Card width in pixels. Defaults to 1200. */
  width?: number;
  /** Card height in pixels. Defaults to 630. */
  height?: number;
  /** Zod object schema. Every string field must specify a finite .max(n) cap. */
  params: TSchema;
  /** Required sample input used by previews, gallery, playground, and CI. */
  sample: z.input<TSchema>;
  /** Pure render function returning Satori-compatible JSX (inline styles, flexbox only). */
  render: (params: z.infer<TSchema>, ctx: TemplateRenderContext) => ReactElement;
}

/**
 * Type-erased template view for heterogeneous template registries.
 * `params: never` preserves contravariance without resorting to `any`,
 * because callers validate inputs with `template.params` before rendering.
 */
export interface RegisteredTemplate {
  id: string;
  name: string;
  description: string;
  width?: number;
  height?: number;
  params: z.ZodObject;
  sample: Record<string, unknown>;
  render: (params: never, ctx: TemplateRenderContext) => ReactElement;
}

interface ZodLikeDef {
  type?: string;
  innerType?: unknown;
  element?: unknown;
}

interface ZodLikeNode {
  def?: ZodLikeDef;
  maxLength?: number | null;
  shape?: Record<string, unknown>;
}

const TEMPLATE_ID_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

function isZodLikeNode(value: unknown): value is ZodLikeNode {
  return typeof value === "object" && value !== null;
}

function unwrapSchema(schema: unknown): ZodLikeNode | null {
  let current: unknown = schema;
  const visited = new Set<unknown>();
  while (isZodLikeNode(current) && current.def?.innerType !== undefined) {
    if (visited.has(current)) break;
    visited.add(current);
    current = current.def.innerType;
  }
  return isZodLikeNode(current) ? current : null;
}

function assertFieldHasMaxLength(
  templateId: string,
  fieldPath: string,
  schema: unknown,
): void {
  const unwrapped = unwrapSchema(schema);
  if (!unwrapped?.def) return;

  const schemaType = unwrapped.def.type;

  if (schemaType === "string") {
    const maxLen = unwrapped.maxLength;
    if (typeof maxLen !== "number" || !Number.isFinite(maxLen) || maxLen <= 0) {
      throw new Error(
        `Template "${templateId}" string parameter "${fieldPath}" must declare a positive .max(n) length cap.`,
      );
    }
    return;
  }

  if (schemaType === "array" && unwrapped.def.element !== undefined) {
    assertFieldHasMaxLength(templateId, `${fieldPath}[]`, unwrapped.def.element);
    return;
  }

  if (schemaType === "object" && unwrapped.shape) {
    for (const [key, nested] of Object.entries(unwrapped.shape)) {
      assertFieldHasMaxLength(templateId, `${fieldPath}.${key}`, nested);
    }
  }
}

export function assertStringFieldsHaveMaxLength(
  templateId: string,
  schema: z.ZodObject,
): void {
  for (const [field, fieldSchema] of Object.entries(schema.shape)) {
    assertFieldHasMaxLength(templateId, field, fieldSchema);
  }
}

export function defineTemplate<TSchema extends z.ZodObject>(
  definition: TemplateDefinition<TSchema>,
): TemplateDefinition<TSchema> {
  if (!TEMPLATE_ID_PATTERN.test(definition.id)) {
    throw new Error(
      `Template id "${definition.id}" must be kebab-case (lowercase letters, digits, and hyphens).`,
    );
  }

  if (definition.name.trim().length === 0) {
    throw new Error(`Template "${definition.id}" must provide a non-empty name.`);
  }

  assertStringFieldsHaveMaxLength(definition.id, definition.params);

  const parsedSample = definition.params.safeParse(definition.sample);
  if (!parsedSample.success) {
    const firstIssue = parsedSample.error.issues[0];
    const detail = firstIssue
      ? `${firstIssue.path.join(".") || "sample"}: ${firstIssue.message}`
      : "invalid sample data";
    throw new Error(
      `Template "${definition.id}" has invalid sample data (${detail}).`,
    );
  }

  const sampleScriptIssues = findUnsupportedScripts(
    parsedSample.data as Record<string, unknown>,
  );
  if (sampleScriptIssues.length > 0) {
    const first = sampleScriptIssues[0];
    throw new Error(
      `Template "${definition.id}" sample field "${first.field}" uses unsupported script "${first.script}": ${first.reason}`,
    );
  }

  return definition;
}

export const RESERVED_QUERY_KEYS = [
  "template",
  "fallbackLabel",
  "emoji",
] as const;

export function coerceSearchParams(
  searchParams: URLSearchParams,
  schema: z.ZodObject,
  reservedKeys: readonly string[] = RESERVED_QUERY_KEYS,
): Record<string, unknown> {
  const reserved = new Set(reservedKeys);
  const shape = schema.shape as Record<string, unknown>;
  const result: Record<string, unknown> = {};

  for (const [key, raw] of searchParams.entries()) {
    if (reserved.has(key)) continue;

    const fieldSchema = shape[key];
    const unwrapped = unwrapSchema(fieldSchema);
    const fieldType = unwrapped?.def?.type;

    if (fieldType === "number") {
      if (raw.trim() !== "") {
        const numeric = Number(raw);
        result[key] = Number.isFinite(numeric) ? numeric : raw;
      } else {
        result[key] = raw;
      }
      continue;
    }

    if (fieldType === "boolean") {
      if (raw === "true") {
        result[key] = true;
      } else if (raw === "false") {
        result[key] = false;
      } else {
        result[key] = raw;
      }
      continue;
    }

    result[key] = raw;
  }

  return result;
}

export function extractTemplateParamsFromSearchParams(
  searchParams: URLSearchParams,
  template: RegisteredTemplate,
  reservedKeys: readonly string[] = RESERVED_QUERY_KEYS,
): unknown {
  const reserved = new Set(reservedKeys);
  const hasTemplateParams = Array.from(searchParams.keys()).some(
    (key) => !reserved.has(key),
  );

  if (!hasTemplateParams) {
    return template.sample;
  }

  return coerceSearchParams(searchParams, template.params, reservedKeys);
}

import { access, readFile } from "node:fs/promises";
import path from "node:path";

export type SupportedScript = "latin" | "cyrillic" | "japanese";

export type UnsupportedScript =
  | "latin-extended"
  | "cyrillic-extended"
  | "greek"
  | "chinese"
  | "hangul"
  | "devanagari"
  | "arabic"
  | "hebrew"
  | "thai"
  | "indic-other"
  | "southeast-asian"
  | "emoji"
  | "other";

export type ScriptId = SupportedScript | UnsupportedScript;

/**
 * Scripts supported out of the box by the bundled default font (Geist-Regular.ttf).
 */
export const BASE_SUPPORTED_SCRIPTS: readonly SupportedScript[] = [
  "latin",
  "cyrillic",
] as const;

export const supportedScripts = BASE_SUPPORTED_SCRIPTS;

export interface LoadedFont {
  name: string;
  data: ArrayBuffer;
  weight: 100 | 200 | 300 | 400 | 500 | 600 | 700 | 800 | 900;
  style: "normal" | "italic";
}

export interface UnsupportedScriptIssue {
  field: string;
  script: ScriptId;
  reason: string;
  sampleChar: string;
}

export interface EmojiWarning {
  field: string;
  removed: string[];
  reason: string;
}

export class UnsupportedScriptError extends Error {
  readonly code = "UNSUPPORTED_SCRIPT" as const;
  readonly issues: readonly UnsupportedScriptIssue[];
  readonly scripts: readonly ScriptId[];

  constructor(issues: readonly UnsupportedScriptIssue[]) {
    const uniqueScripts = Array.from(new Set(issues.map((i) => i.script)));
    const summary = issues
      .map((i) => `${i.field}: ${i.script} (${i.reason})`)
      .join("; ");
    super(`Unsupported script detected: ${summary}`);
    this.name = "UnsupportedScriptError";
    this.issues = issues;
    this.scripts = uniqueScripts;
  }
}

