const DEFAULT_LATIN_FONT_RELATIVE_PATH = "registry/fonts/Geist-Regular.ttf";
const DEFAULT_LATIN_BOLD_FONT_RELATIVE_PATH = "registry/fonts/Geist-Bold.ttf";
const JAPANESE_FONT_RELATIVE_PATH = "registry/fonts/cjk/NotoSansJP-Regular.ttf";

interface CachedFontEntry {
  data: ArrayBuffer;
  cmap: ReadonlySet<number>;
}

const fontCache = new Map<string, Promise<CachedFontEntry>>();
const graphemeSegmenter = new Intl.Segmenter("en", { granularity: "grapheme" });

const EMOJI_BASE_RE = /\p{Extended_Pictographic}|\p{Regional_Indicator}/u;
const UNICODE_EMOJI_RE = /\p{Emoji}/u;
const ASCII_DIGIT_HASH_STAR_RE = /^[#*0-9]$/;

export function clearFontCache(): void {
  fontCache.clear();
}

export function getCachedFontPaths(): string[] {
  return Array.from(fontCache.keys());
}

export function isCodepointInGeist(cp: number): boolean {
  let low = 0;
  let high = GEIST_COVERED_RANGES.length - 1;
  while (low <= high) {
    const mid = (low + high) >>> 1;
    const [start, end] = GEIST_COVERED_RANGES[mid];
    if (cp < start) {
      high = mid - 1;
    } else if (cp > end) {
      low = mid + 1;
    } else {
      return true;
    }
  }
  return false;
}

/**
 * Parses Unicode cmap subtables (Format 4 and Format 12) from a TrueType/OpenType font.
 */
export function parseTtfCmapCodepoints(buffer: ArrayBuffer): Set<number> {
  const view = new DataView(buffer);
  const numTables = view.getUint16(4, false);
  let cmapOffset = -1;

  for (let i = 0; i < numTables; i++) {
    const recOffset = 12 + i * 16;
    const tag = String.fromCharCode(
      view.getUint8(recOffset),
      view.getUint8(recOffset + 1),
      view.getUint8(recOffset + 2),
      view.getUint8(recOffset + 3),
    );
    if (tag === "cmap") {
      cmapOffset = view.getUint32(recOffset + 8, false);
      break;
    }
  }

  if (cmapOffset < 0) {
    throw new Error("Font binary does not contain a cmap table.");
  }

  const numSubtables = view.getUint16(cmapOffset + 2, false);
  let format12Offset = -1;
  let format4Offset = -1;

  for (let i = 0; i < numSubtables; i++) {
    const entryOffset = cmapOffset + 4 + i * 8;
    const platformId = view.getUint16(entryOffset, false);
    const encodingId = view.getUint16(entryOffset + 2, false);
    const isUnicodeSubtable =
      platformId === 0 ||
      (platformId === 3 && (encodingId === 1 || encodingId === 10));
    if (!isUnicodeSubtable) continue;

    const subtableOffset = cmapOffset + view.getUint32(entryOffset + 4, false);
    const format = view.getUint16(subtableOffset, false);
    if (format === 12 && format12Offset < 0) {
      format12Offset = subtableOffset;
    } else if (format === 4 && format4Offset < 0) {
      format4Offset = subtableOffset;
    }
  }

  const codepoints = new Set<number>();

  if (format12Offset >= 0) {
    const numGroups = view.getUint32(format12Offset + 12, false);
    for (let i = 0; i < numGroups; i++) {
      const groupOffset = format12Offset + 16 + i * 12;
      const startCharCode = view.getUint32(groupOffset, false);
      const endCharCode = view.getUint32(groupOffset + 4, false);
      for (let cp = startCharCode; cp <= endCharCode; cp++) {
        codepoints.add(cp);
      }
    }
    return codepoints;
  }

  if (format4Offset >= 0) {
    const segCount = view.getUint16(format4Offset + 6, false) >>> 1;
    const endCodeOffset = format4Offset + 14;
    const startCodeOffset = endCodeOffset + 2 + segCount * 2;
    const idDeltaOffset = startCodeOffset + segCount * 2;
    const idRangeOffset = idDeltaOffset + segCount * 2;

    for (let i = 0; i < segCount; i++) {
      const endCode = view.getUint16(endCodeOffset + i * 2, false);
      const startCode = view.getUint16(startCodeOffset + i * 2, false);
      const idDelta = view.getInt16(idDeltaOffset + i * 2, false);
      const rangeOffset = view.getUint16(idRangeOffset + i * 2, false);

      if (startCode === 0xffff) continue;

      for (let cp = startCode; cp <= endCode; cp++) {
        let glyphId: number;
        if (rangeOffset === 0) {
          glyphId = (cp + idDelta) & 0xffff;
        } else {
          const glyphOffset =
            idRangeOffset + i * 2 + rangeOffset + (cp - startCode) * 2;
          glyphId = view.getUint16(glyphOffset, false);
          if (glyphId !== 0) {
            glyphId = (glyphId + idDelta) & 0xffff;
          }
        }
        if (glyphId !== 0) {
          codepoints.add(cp);
        }
      }
    }
    return codepoints;
  }

  throw new Error("Font binary does not contain a Unicode format 4 or 12 cmap.");
}

function isEmojiGrapheme(grapheme: string): boolean {
  for (const ch of grapheme) {
    const cp = ch.codePointAt(0);
    if (cp === undefined) continue;

    // Variation Selector-16, Keycap combiner, ZWJ, or Supplementary Emoji blocks
    // always route through Satori's Twemoji CDN fetch.
    if (
      cp === 0xfe0f ||
      cp === 0x20e3 ||
      cp === 0x200d ||
      (cp >= 0x1f000 && cp <= 0x1faff) ||
      (cp >= 0x1f3fb && cp <= 0x1f3ff)
    ) {
      return true;
    }

    if (
      EMOJI_BASE_RE.test(ch) ||
      (UNICODE_EMOJI_RE.test(ch) && !ASCII_DIGIT_HASH_STAR_RE.test(ch))
    ) {
      // Plain text-presentation symbols mapped directly inside Geist (e.g. ☺, ☹, ©, ®, ™)
      // render offline without triggering a CDN fetch when not paired with VS16.
      if (!isCodepointInGeist(cp)) {
        return true;
      }
    }
  }
  return false;
}

function isWhitespaceOrFormat(cp: number): boolean {
  return cp === 0x09 || cp === 0x0a || cp === 0x0d || cp === 0x200c;
}

function isLatinCodepoint(cp: number): boolean {
  return (
    (cp >= 0x0041 && cp <= 0x005a) ||
    (cp >= 0x0061 && cp <= 0x007a) ||
    (cp >= 0x00c0 && cp <= 0x00d6) ||
    (cp >= 0x00d8 && cp <= 0x00f6) ||
    (cp >= 0x00f8 && cp <= 0x02af) ||
    (cp >= 0x1e00 && cp <= 0x1eff) ||
    (cp >= 0x2c60 && cp <= 0x2c7f) ||
    (cp >= 0xa720 && cp <= 0xa7ff) ||
    (cp >= 0xab30 && cp <= 0xab6f) ||
    (cp >= 0xfb00 && cp <= 0xfb06)
  );
}

function isCyrillicCodepoint(cp: number): boolean {
  return (
    (cp >= 0x0400 && cp <= 0x052f) ||
    (cp >= 0x2de0 && cp <= 0x2dff) ||
    (cp >= 0xa640 && cp <= 0xa69f)
  );
}

function isGreekCodepoint(cp: number): boolean {
  return (cp >= 0x0370 && cp <= 0x03ff) || (cp >= 0x1f00 && cp <= 0x1fff);
}

function isHangulCodepoint(cp: number): boolean {
  return (
    (cp >= 0x1100 && cp <= 0x11ff) ||
    (cp >= 0x3130 && cp <= 0x318f) ||
    (cp >= 0xa960 && cp <= 0xa97f) ||
    (cp >= 0xac00 && cp <= 0xd7af) ||
    (cp >= 0xd7b0 && cp <= 0xd7ff)
  );
}

function isHanCodepoint(cp: number): boolean {
  return (
    (cp >= 0x3400 && cp <= 0x4dbf) ||
    (cp >= 0x4e00 && cp <= 0x9fff) ||
    (cp >= 0xf900 && cp <= 0xfaff)
  );
}

function isJapaneseScriptCodepoint(cp: number): boolean {
  return (
    (cp >= 0x3000 && cp <= 0x303f) ||
    (cp >= 0x3040 && cp <= 0x309f) ||
    (cp >= 0x30a0 && cp <= 0x30ff) ||
    (cp >= 0x31f0 && cp <= 0x31ff) ||
    (cp >= 0xff00 && cp <= 0xffef)
  );
}

function classifyNonEmojiCodepoint(
  cp: number,
  japaneseCmap?: ReadonlySet<number>,
): ScriptId | null {
  if (isWhitespaceOrFormat(cp)) return null;

  // Treat Greek letters as Greek script even when Geist happens to include
  // individual math/unit symbols like π or Ω.
  if (isGreekCodepoint(cp)) return "greek";

  if (isLatinCodepoint(cp)) {
    return isCodepointInGeist(cp) ? "latin" : "latin-extended";
  }

  if (isCyrillicCodepoint(cp)) {
    return isCodepointInGeist(cp) ? "cyrillic" : "cyrillic-extended";
  }

  if (isCodepointInGeist(cp)) {
    // Digits, ASCII punctuation, spaces, currency, arrows, and math symbols
    // covered by Geist render without any additional font or network call.
    return null;
  }

  if (isHangulCodepoint(cp)) return "hangul";

  if (
    (cp >= 0x3100 && cp <= 0x312f) ||
    (cp >= 0x31a0 && cp <= 0x31bf) ||
    (cp >= 0x20000 && cp <= 0x2ebef)
  ) {
    return "chinese";
  }

  if (isJapaneseScriptCodepoint(cp)) return "japanese";

  if (isHanCodepoint(cp)) {
    if (japaneseCmap) {
      return japaneseCmap.has(cp) ? "japanese" : "chinese";
    }
    return SIMPLIFIED_CHINESE_ONLY_CPS.has(cp) ? "chinese" : "japanese";
  }

  if ((cp >= 0x0900 && cp <= 0x097f) || (cp >= 0xa8e0 && cp <= 0xa8ff)) {
    return "devanagari";
  }

  if (
    (cp >= 0x0600 && cp <= 0x06ff) ||
    (cp >= 0x0750 && cp <= 0x077f) ||
    (cp >= 0x08a0 && cp <= 0x08ff) ||
    (cp >= 0xfb50 && cp <= 0xfdff) ||
    (cp >= 0xfe70 && cp <= 0xfeff)
  ) {
    return "arabic";
  }

  if ((cp >= 0x0590 && cp <= 0x05ff) || (cp >= 0xfb1d && cp <= 0xfb4f)) {
    return "hebrew";
  }

  if (cp >= 0x0980 && cp <= 0x0dff) {
    return "indic-other";
  }

  if (cp >= 0x0e00 && cp <= 0x0e7f) {
    return "thai";
  }

  if ((cp >= 0x0e80 && cp <= 0x109f) || (cp >= 0x1780 && cp <= 0x17ff)) {
    return "southeast-asian";
  }

  return "other";
}

function describeUnsupportedScript(
  script: ScriptId,
  options?: { japanesePackInstalled?: boolean },
): string {
  switch (script) {
    case "japanese":
      return options?.japanesePackInstalled
        ? "Japanese font pack is unavailable."
        : "Japanese requires the opt-in NotoSansJP font pack (registry/fonts/cjk/NotoSansJP-Regular.ttf or ogami/fonts/cjk/NotoSansJP-Regular.ttf).";
    case "latin-extended":
      return "Character is outside the default Geist-Regular.ttf Latin glyph set.";
    case "cyrillic-extended":
      return "Cyrillic character is outside the default Geist-Regular.ttf glyph set.";
    case "greek":
      return "Greek is not covered by Geist-Regular.ttf (only 6 technical/math symbols are included).";
    case "chinese":
      return "Simplified/Traditional Chinese characters outside Japanese JIS coverage are not supported by NotoSansJP.";
    case "hangul":
      return "Korean (Hangul) is not covered by Geist-Regular.ttf or NotoSansJP.";
    case "devanagari":
      return "Devanagari requires OpenType Indic shaping that Satori does not perform (produces broken conjuncts and vowel signs).";
    case "arabic":
      return "Arabic crashes Satori/opentype.js (GSUB lookupType 5 substFormat 3 is unsupported) and lacks RTL shaping.";
    case "hebrew":
      return "Hebrew RTL text and diacritic shaping are unverified and unsupported in v1.";
    case "thai":
      return "Thai mark positioning and word segmentation are not supported by Satori.";
    case "indic-other":
      return "Indic scripts require complex OpenType shaping that Satori does not perform.";
    case "southeast-asian":
      return "Complex Southeast Asian scripts are not supported by Satori or bundled fonts.";
    case "emoji":
      return "Emoji characters trigger an external CDN fetch (cdn.jsdelivr.net/gh/twitter/twemoji) in next/og, which violates offline rendering.";
    case "other":
    default:
      return "Text contains characters not covered by the installed fonts.";
  }
}

export function detectScripts(
  text: string,
  options?: { japaneseCmap?: ReadonlySet<number> },
): ScriptId[] {
  const found = new Set<ScriptId>();
  for (const { segment } of graphemeSegmenter.segment(text)) {
    if (isEmojiGrapheme(segment)) {
      found.add("emoji");
      continue;
    }
    for (const ch of segment) {
      const cp = ch.codePointAt(0);
      if (cp === undefined) continue;
      const script = classifyNonEmojiCodepoint(cp, options?.japaneseCmap);
      if (script) {
        found.add(script);
      }
    }
  }
  return Array.from(found);
}

const EMOJI_STRIP_REASON =
  "Emoji characters were stripped because next/og fetches emoji SVGs over the network at render time.";

export function stripEmojiFromText(text: string): {
  cleaned: string;
  removed: string[];
} {
  const removed: string[] = [];
  const kept: string[] = [];

  for (const { segment } of graphemeSegmenter.segment(text)) {
    if (isEmojiGrapheme(segment)) {
      removed.push(segment);
    } else {
      kept.push(segment);
    }
  }

  if (removed.length === 0) {
    return { cleaned: text, removed };
  }

  // Collapse extra spaces introduced when stripping inline or edge emojis.
  const cleaned = kept.join("").replace(/ {2,}/g, " ").trim();
  return { cleaned, removed };
}

function stripEmojiValue(
  value: unknown,
  prefix: string,
  warnings: EmojiWarning[],
): unknown {
  if (typeof value === "string") {
    const { cleaned, removed } = stripEmojiFromText(value);
    if (removed.length > 0) {
      warnings.push({
        field: prefix,
        removed: Array.from(new Set(removed)),
        reason: EMOJI_STRIP_REASON,
      });
    }
    return cleaned;
  }

  if (Array.isArray(value)) {
    return value.map((item, index) =>
      stripEmojiValue(item, `${prefix}[${index}]`, warnings),
    );
  }

  if (value !== null && typeof value === "object") {
    const result: Record<string, unknown> = {};
    for (const [key, nested] of Object.entries(value)) {
      const nextPrefix = prefix ? `${prefix}.${key}` : key;
      result[key] = stripEmojiValue(nested, nextPrefix, warnings);
    }
    return result;
  }

  return value;
}

export function stripEmojiFromParams<T extends Record<string, unknown>>(
  inputs: T,
): { sanitized: T; warnings: EmojiWarning[] } {
  const warnings: EmojiWarning[] = [];
  const sanitized = stripEmojiValue(inputs, "", warnings) as T;
  return { sanitized, warnings };
}

export function detectScriptsInParams(
  inputs: Record<string, unknown>,
  options?: { japaneseCmap?: ReadonlySet<number> },
): ScriptId[] {
  const fields: Array<{ field: string; text: string }> = [];
  collectStringFields(inputs, "", fields);
  const found = new Set<ScriptId>();
  for (const { text } of fields) {
    for (const script of detectScripts(text, options)) {
      found.add(script);
    }
  }
  return Array.from(found);
}

function collectStringFields(
  value: unknown,
  prefix: string,
  out: Array<{ field: string; text: string }>,
): void {
  if (typeof value === "string") {
    out.push({ field: prefix, text: value });
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((item, index) => {
      collectStringFields(item, `${prefix}[${index}]`, out);
    });
    return;
  }
  if (value !== null && typeof value === "object") {
    for (const [key, nested] of Object.entries(value)) {
      const nextPrefix = prefix ? `${prefix}.${key}` : key;
      collectStringFields(nested, nextPrefix, out);
    }
  }
}

export function findUnsupportedScripts(
  inputs: Record<string, unknown>,
  options?: {
    supportedScripts?: readonly SupportedScript[];
    japaneseCmap?: ReadonlySet<number>;
  },
): UnsupportedScriptIssue[] {
  const allowed = new Set<ScriptId>(
    options?.supportedScripts ?? BASE_SUPPORTED_SCRIPTS,
  );
  const japanesePackInstalled = allowed.has("japanese");
  const fields: Array<{ field: string; text: string }> = [];
  collectStringFields(inputs, "", fields);

  const issues: UnsupportedScriptIssue[] = [];

  for (const { field, text } of fields) {
    const seenForField = new Set<ScriptId>();

    for (const { segment } of graphemeSegmenter.segment(text)) {
      if (isEmojiGrapheme(segment)) {
        if (!seenForField.has("emoji")) {
          seenForField.add("emoji");
          issues.push({
            field,
            script: "emoji",
            reason: describeUnsupportedScript("emoji", {
              japanesePackInstalled,
            }),
            sampleChar: segment,
          });
        }
        continue;
      }

      for (const ch of segment) {
        const cp = ch.codePointAt(0);
        if (cp === undefined) continue;
        const script = classifyNonEmojiCodepoint(cp, options?.japaneseCmap);
        if (script && !allowed.has(script) && !seenForField.has(script)) {
          seenForField.add(script);
          issues.push({
            field,
            script,
            reason: describeUnsupportedScript(script, {
              japanesePackInstalled,
            }),
            sampleChar: ch,
          });
        }
      }
    }
  }

  return issues;
}

type KnownFontFile =
  | "Geist-Regular.ttf"
  | "Geist-Bold.ttf"
  | "cjk/NotoSansJP-Regular.ttf";

async function ignoreMissing(promise: Promise<Buffer>): Promise<Buffer | null> {
  try {
    return await promise;
  } catch {
    return null;
  }
}

async function ignoreMissingAccess(promise: Promise<void>): Promise<boolean> {
  try {
    await promise;
    return true;
  } catch {
    return false;
  }
}

async function readCustomFontsDirFont(
  fontFile: KnownFontFile,
): Promise<Buffer | null> {
  const customDir = process.env.OGAMI_FONTS_DIR?.trim();
  if (!customDir) return null;

  if (fontFile === "Geist-Regular.ttf") {
    return ignoreMissing(
      readFile(/*turbopackIgnore: true*/ path.join(customDir, "Geist-Regular.ttf")),
    );
  }
  if (fontFile === "Geist-Bold.ttf") {
    return ignoreMissing(
      readFile(/*turbopackIgnore: true*/ path.join(customDir, "Geist-Bold.ttf")),
    );
  }
  return ignoreMissing(
    readFile(
      /*turbopackIgnore: true*/ path.join(
        customDir,
        "cjk",
        "NotoSansJP-Regular.ttf",
      ),
    ),
  );
}

async function readFontBuffer(fontFile: KnownFontFile): Promise<Buffer> {
  const customBuffer = await readCustomFontsDirFont(fontFile);
  if (customBuffer) return customBuffer;

  if (fontFile === "Geist-Regular.ttf") {
    const buffer =
      (await ignoreMissing(
        readFile(
          path.join(process.cwd(), "registry", "fonts", "Geist-Regular.ttf"),
        ),
      )) ??
      (await ignoreMissing(
        readFile(
          path.join(process.cwd(), "ogami", "fonts", "Geist-Regular.ttf"),
        ),
      )) ??
      (await ignoreMissing(
        readFile(
          path.join(
            process.cwd(),
            "node_modules",
            "geist",
            "dist",
            "fonts",
            "geist-sans",
            "Geist-Regular.ttf",
          ),
        ),
      )) ??
      (await ignoreMissing(
        readFile(
          /*turbopackIgnore: true*/ path.join(
            process.cwd(),
            "..",
            "node_modules",
            "geist",
            "dist",
            "fonts",
            "geist-sans",
            "Geist-Regular.ttf",
          ),
        ),
      )) ??
      (await ignoreMissing(
        readFile(
          /*turbopackIgnore: true*/ path.join(
            process.cwd(),
            "..",
            "..",
            "node_modules",
            "geist",
            "dist",
            "fonts",
            "geist-sans",
            "Geist-Regular.ttf",
          ),
        ),
      ));
    if (buffer) return buffer;
  } else if (fontFile === "Geist-Bold.ttf") {
    const buffer =
      (await ignoreMissing(
        readFile(
          path.join(process.cwd(), "registry", "fonts", "Geist-Bold.ttf"),
        ),
      )) ??
      (await ignoreMissing(
        readFile(path.join(process.cwd(), "ogami", "fonts", "Geist-Bold.ttf")),
      )) ??
      (await ignoreMissing(
        readFile(
          path.join(
            process.cwd(),
            "node_modules",
            "geist",
            "dist",
            "fonts",
            "geist-sans",
            "Geist-Bold.ttf",
          ),
        ),
      )) ??
      (await ignoreMissing(
        readFile(
          /*turbopackIgnore: true*/ path.join(
            process.cwd(),
            "..",
            "node_modules",
            "geist",
            "dist",
            "fonts",
            "geist-sans",
            "Geist-Bold.ttf",
          ),
        ),
      )) ??
      (await ignoreMissing(
        readFile(
          /*turbopackIgnore: true*/ path.join(
            process.cwd(),
            "..",
            "..",
            "node_modules",
            "geist",
            "dist",
            "fonts",
            "geist-sans",
            "Geist-Bold.ttf",
          ),
        ),
      ));
    if (buffer) return buffer;
  } else {
    const buffer =
      (await ignoreMissing(
        readFile(
          path.join(
            process.cwd(),
            "registry",
            "fonts",
            "cjk",
            "NotoSansJP-Regular.ttf",
          ),
        ),
      )) ??
      (await ignoreMissing(
        readFile(
          path.join(
            process.cwd(),
            "ogami",
            "fonts",
            "cjk",
            "NotoSansJP-Regular.ttf",
          ),
        ),
      ));
    if (buffer) return buffer;
  }

  throw new Error(
    `Could not find font "${fontFile}". Install the "geist" npm package, place fonts in ogami/fonts/, or set OGAMI_FONTS_DIR.`,
  );
}

async function readFontEntry(
  cacheKey: string,
  fontFile: KnownFontFile,
): Promise<CachedFontEntry> {
  const cached = fontCache.get(cacheKey);
  if (cached) {
    return cached;
  }

  const loadPromise = (async (): Promise<CachedFontEntry> => {
    const buffer = await readFontBuffer(fontFile);
    const data = new ArrayBuffer(buffer.byteLength);
    new Uint8Array(data).set(buffer);
    const cmap = parseTtfCmapCodepoints(data);
    return { data, cmap };
  })();

  // Store promise so concurrent cold requests share a single disk read,
  // and evict if reading fails so transient FS issues can recover.
  fontCache.set(cacheKey, loadPromise);
  loadPromise.catch(() => {
    fontCache.delete(cacheKey);
  });

  return loadPromise;
}

export async function hasJapaneseFontPack(): Promise<boolean> {
  if (fontCache.has(JAPANESE_FONT_RELATIVE_PATH)) {
    try {
      await fontCache.get(JAPANESE_FONT_RELATIVE_PATH);
      return true;
    } catch {
      return false;
    }
  }
  const customDir = process.env.OGAMI_FONTS_DIR?.trim();
  if (
    customDir &&
    (await ignoreMissingAccess(
      access(
        /*turbopackIgnore: true*/ path.join(
          customDir,
          "cjk",
          "NotoSansJP-Regular.ttf",
        ),
      ),
    ))
  ) {
    return true;
  }
  if (
    await ignoreMissingAccess(
      access(
        path.join(
          process.cwd(),
          "registry",
          "fonts",
          "cjk",
          "NotoSansJP-Regular.ttf",
        ),
      ),
    )
  ) {
    return true;
  }
  return ignoreMissingAccess(
    access(
      path.join(
        process.cwd(),
        "ogami",
        "fonts",
        "cjk",
        "NotoSansJP-Regular.ttf",
      ),
    ),
  );
}

export async function getSupportedScripts(): Promise<SupportedScript[]> {
  if (await hasJapaneseFontPack()) {
    return ["latin", "cyrillic", "japanese"];
  }
  return [...BASE_SUPPORTED_SCRIPTS];
}

export async function getJapaneseFontCmap(): Promise<ReadonlySet<number> | null> {
  if (!(await hasJapaneseFontPack())) {
    return null;
  }
  const entry = await readFontEntry(
    JAPANESE_FONT_RELATIVE_PATH,
    "cjk/NotoSansJP-Regular.ttf",
  );
  return entry.cmap;
}

export async function loadFontsForScripts(
  scripts: readonly ScriptId[],
): Promise<LoadedFont[]> {
  const [geistRegular, geistBold] = await Promise.all([
    readFontEntry(DEFAULT_LATIN_FONT_RELATIVE_PATH, "Geist-Regular.ttf"),
    readFontEntry(DEFAULT_LATIN_BOLD_FONT_RELATIVE_PATH, "Geist-Bold.ttf"),
  ]);
  const loaded: LoadedFont[] = [
    {
      name: "Geist",
      data: geistRegular.data,
      weight: 400,
      style: "normal",
    },
    {
      name: "Geist",
      data: geistBold.data,
      weight: 700,
      style: "normal",
    },
  ];

  if (scripts.includes("japanese")) {
    const installed = await hasJapaneseFontPack();
    if (!installed) {
      throw new UnsupportedScriptError([
        {
          field: "text",
          script: "japanese",
          reason: describeUnsupportedScript("japanese", {
            japanesePackInstalled: false,
          }),
          sampleChar: "あ",
        },
      ]);
    }
    const notoJp = await readFontEntry(
      JAPANESE_FONT_RELATIVE_PATH,
      "cjk/NotoSansJP-Regular.ttf",
    );
    loaded.push({
      name: "Noto Sans JP",
      data: notoJp.data,
      weight: 400,
      style: "normal",
    });
  }

  return loaded;
}

import { ImageResponse } from "next/og";
import { z } from "zod";
import { autoFit } from "./auto-fit";
import type {
  RegisteredTemplate,
  TemplateDefinition,
  TemplateRenderContext,
} from "./define-template";
import {
  BASE_SUPPORTED_SCRIPTS,
  UnsupportedScriptError,
  detectScriptsInParams,
  findUnsupportedScripts,
  getJapaneseFontCmap,
  hasJapaneseFontPack,
  loadFontsForScripts,
  stripEmojiFromParams,
  stripEmojiFromText,
  type EmojiWarning,
  type ScriptId,
  type SupportedScript,
} from "./fonts";

export class TemplateValidationError extends Error {
  readonly code = "INVALID_PARAMS" as const;
  readonly templateId: string;
  readonly issues: readonly z.core.$ZodIssue[];

  constructor(templateId: string, issues: readonly z.core.$ZodIssue[]) {
    const summary = issues
      .map((issue) => `${issue.path.join(".") || "params"}: ${issue.message}`)
      .join("; ");
    super(`Invalid parameters for template "${templateId}": ${summary}`);
    this.name = "TemplateValidationError";
    this.templateId = templateId;
    this.issues = issues;
  }
}

export type EmojiMode = "strip" | "fallback";

export interface RenderTemplateOptions {
  /**
   * How to handle emoji characters in text parameters:
   * - "strip" (default): removes emoji graphemes before rendering and reports them in `warnings`.
   * - "fallback": treats emoji as unsupported so the guarded fallback / error path runs.
   */
  emoji?: EmojiMode;
  /**
   * Behavior when an unsupported script is detected:
   * - "fallback" (default): returns a safe Option 1 fallback card (HTTP 200, Cache-Control: no-store).
   * - "return-error": returns `{ ok: false, error: UnsupportedScriptError, warnings }`.
   * - "throw": throws UnsupportedScriptError.
   */
  onUnsupportedScript?: "fallback" | "return-error" | "throw";
  /**
   * Optional label (such as a site or product name) shown on the fallback card.
   * Defaults to `template.name`. Must use only base-supported scripts.
   */
  fallbackLabel?: string;
  /** Optional custom HTTP headers merged onto the normal ImageResponse. */
  headers?: Record<string, string>;
}

export type RenderTemplateResult =
  | {
      ok: true;
      isFallback: false;
      response: ImageResponse;
      detectedScripts: ScriptId[];
      warnings: EmojiWarning[];
    }
  | {
      ok: true;
      isFallback: true;
      response: ImageResponse;
      error: UnsupportedScriptError;
      detectedScripts: ScriptId[];
      warnings: EmojiWarning[];
    }
  | {
      ok: false;
      error: UnsupportedScriptError | TemplateValidationError;
      warnings: EmojiWarning[];
    };

export interface RenderFallbackCardOptions {
  templateId?: string;
  templateName?: string;
  fallbackLabel?: string;
  unsupportedScripts?: readonly ScriptId[];
  warnings?: readonly EmojiWarning[];
  width?: number;
  height?: number;
  headers?: Record<string, string>;
}

const DEFAULT_WIDTH = 1200;
const DEFAULT_HEIGHT = 630;
const MAX_FALLBACK_LABEL_LENGTH = 60;

export const DEFAULT_CACHE_CONTROL =
  "public, max-age=86400, s-maxage=604800, stale-while-revalidate=86400";

function formatEmojiCodePoints(grapheme: string): string {
  return Array.from(grapheme)
    .map((ch) => {
      const cp = ch.codePointAt(0);
      return cp !== undefined ? `U+${cp.toString(16).toUpperCase()}` : "";
    })
    .filter(Boolean)
    .join("+");
}

export function formatWarningsHeader(
  warnings: readonly EmojiWarning[],
): string {
  return warnings
    .map((warning) => {
      const codes = warning.removed.map(formatEmojiCodePoints).join(", ");
      return `${warning.field}: stripped ${warning.removed.length} emoji (${codes})`;
    })
    .join("; ");
}

function sanitizeFallbackText(
  candidate: string | undefined,
): string | null {
  if (!candidate) return null;
  const trimmed = candidate.trim();
  if (!trimmed) return null;
  const { cleaned } = stripEmojiFromText(trimmed);
  if (!cleaned) return null;
  const issues = findUnsupportedScripts(
    { label: cleaned },
    { supportedScripts: BASE_SUPPORTED_SCRIPTS },
  );
  if (issues.length > 0) return null;
  return cleaned.length > MAX_FALLBACK_LABEL_LENGTH
    ? `${cleaned.slice(0, MAX_FALLBACK_LABEL_LENGTH - 3)}...`
    : cleaned;
}

function resolveFallbackLabel(options?: RenderFallbackCardOptions): string {
  return (
    sanitizeFallbackText(options?.fallbackLabel) ??
    sanitizeFallbackText(options?.templateName) ??
    "Preview"
  );
}

/**
 * Renders an Option 1 safe fallback card (HTTP 200, Cache-Control: no-store,
 * X-Ogami-Fallback: true, X-Ogami-Unsupported-Scripts) containing none of the
 * caller's unsupported text parameters.
 */
export async function renderFallbackCard(
  options?: RenderFallbackCardOptions,
): Promise<ImageResponse> {
  const width = options?.width ?? DEFAULT_WIDTH;
  const height = options?.height ?? DEFAULT_HEIGHT;
  const label = resolveFallbackLabel(options);
  const badgeText =
    sanitizeFallbackText(options?.templateId)?.toUpperCase() ?? "SAFE PREVIEW";
  const unsupportedScripts = options?.unsupportedScripts ?? [];
  const fonts = await loadFontsForScripts(["latin"]);
  const showDevNotice = process.env.NODE_ENV === "development";

  const headers = new Headers(options?.headers);
  headers.set("cache-control", "no-store");
  headers.set("x-ogami-fallback", "true");
  headers.set("x-ogami-unsupported-scripts", unsupportedScripts.join(","));
  if (options?.warnings && options.warnings.length > 0) {
    headers.set("x-ogami-warnings", formatWarningsHeader(options.warnings));
  }

  return new ImageResponse(
    (
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          width: "100%",
          height: "100%",
          backgroundColor: "#09090b",
          color: "#fafafa",
          fontFamily: "Geist",
          padding: 48,
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "space-between",
            width: "100%",
            height: "100%",
            border: "1px solid #27272a",
            borderRadius: 20,
            padding: 56,
            backgroundColor: "#111113",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 10,
                padding: "8px 16px",
                borderRadius: 999,
                border: "1px solid #27272a",
                backgroundColor: "#18181b",
                fontSize: 20,
                color: "#a1a1aa",
                letterSpacing: "0.06em",
              }}
            >
              <div
                style={{
                  display: "flex",
                  width: 10,
                  height: 10,
                  borderRadius: 999,
                  backgroundColor: "#38bdf8",
                }}
              />
              <span>{badgeText}</span>
            </div>
          </div>

          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 16,
            }}
          >
            <div
              style={{
                display: "flex",
                fontSize: 64,
                fontWeight: 700,
                lineHeight: 1.15,
                color: "#fafafa",
              }}
            >
              {label}
            </div>
          </div>

          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              borderTop: "1px solid #27272a",
              paddingTop: 24,
              fontSize: 22,
              color: "#a1a1aa",
            }}
          >
            <span>
              {showDevNotice && unsupportedScripts.length > 0
                ? `Fallback card rendered: unsupported script (${unsupportedScripts.join(", ")})`
                : "Ogami"}
            </span>
            <div
              style={{
                display: "flex",
                width: 48,
                height: 6,
                borderRadius: 999,
                backgroundColor: "#38bdf8",
              }}
            />
          </div>
        </div>
      </div>
    ),
    {
      width,
      height,
      fonts,
      status: 200,
      headers: Object.fromEntries(headers.entries()),
    },
  );
}

export async function renderTemplate<TSchema extends z.ZodObject>(
  template: TemplateDefinition<TSchema> | RegisteredTemplate,
  rawParams: unknown,
  options?: RenderTemplateOptions,
): Promise<RenderTemplateResult> {
  const parsed = template.params.safeParse(rawParams);
  if (!parsed.success) {
    return {
      ok: false,
      error: new TemplateValidationError(template.id, parsed.error.issues),
      warnings: [],
    };
  }

  const emojiMode: EmojiMode = options?.emoji ?? "strip";
  let activeParams = parsed.data;
  let warnings: EmojiWarning[] = [];

  if (emojiMode === "strip") {
    const stripped = stripEmojiFromParams(
      parsed.data as Record<string, unknown>,
    );
    activeParams = stripped.sanitized as z.infer<TSchema>;
    warnings = stripped.warnings;
  }

  const activeRecord = activeParams as Record<string, unknown>;
  const detectedScripts = detectScriptsInParams(activeRecord);

  // Only inspect NotoSansJP-Regular.ttf if the text actually contains Japanese characters,
  // ensuring Latin/Cyrillic requests never perform disk I/O on multi-MB font packs.
  let supported: readonly SupportedScript[] = BASE_SUPPORTED_SCRIPTS;
  let japaneseCmap: ReadonlySet<number> | undefined;

  if (detectedScripts.includes("japanese") && (await hasJapaneseFontPack())) {
    supported = ["latin", "cyrillic", "japanese"];
    japaneseCmap = (await getJapaneseFontCmap()) ?? undefined;
  }

  const issues = findUnsupportedScripts(activeRecord, {
    supportedScripts: supported,
    japaneseCmap,
  });

  if (issues.length > 0) {
    const error = new UnsupportedScriptError(issues);
    const behavior = options?.onUnsupportedScript ?? "fallback";

    if (behavior === "throw") {
      throw error;
    }

    if (behavior === "return-error") {
      return {
        ok: false,
        error,
        warnings,
      };
    }

    const response = await renderFallbackCard({
      templateId: template.id,
      templateName: template.name,
      fallbackLabel: options?.fallbackLabel,
      unsupportedScripts: error.scripts,
      warnings,
      width: template.width,
      height: template.height,
      headers: options?.headers,
    });

    return {
      ok: true,
      isFallback: true,
      response,
      error,
      detectedScripts,
      warnings,
    };
  }

  const width = template.width ?? DEFAULT_WIDTH;
  const height = template.height ?? DEFAULT_HEIGHT;
  const fonts = await loadFontsForScripts(detectedScripts);

  const ctx: TemplateRenderContext = {
    width,
    height,
    fonts,
    detectedScripts,
    autoFit,
  };

  const element = (template as RegisteredTemplate).render(
    activeParams as never,
    ctx,
  );

  const responseHeaders = new Headers(options?.headers);
  if (!responseHeaders.has("cache-control")) {
    responseHeaders.set("cache-control", DEFAULT_CACHE_CONTROL);
  }
  if (warnings.length > 0) {
    responseHeaders.set("x-ogami-warnings", formatWarningsHeader(warnings));
  }

  const response = new ImageResponse(element, {
    width,
    height,
    fonts,
    headers: Object.fromEntries(responseHeaders.entries()),
  });

  return {
    ok: true,
    isFallback: false,
    response,
    detectedScripts,
    warnings,
  };
}

